const updateAgentAction = `-- name: UpdateAgentAction :execrows
UPDATE agent_actions
SET status         = ?1,
    compensation   = ?2,
    target_version = ?3,
    undo_refusal   = ?4,
    version        = version + 1,
    updated_at     = ?5
WHERE id = ?6 AND version = ?7
`

type UpdateAgentActionParams struct {
	Status          string
	Compensation    sql.NullString
	TargetVersion   int64
	UndoRefusal     string
	UpdatedAt       int64
	ID              string
	ExpectedVersion int64
}

// Compare-and-swap on the loaded version; the call and its intent never change.
func (q *Queries) UpdateAgentAction(ctx context.Context, arg UpdateAgentActionParams) (int64, error) {
	result, err := q.db.ExecContext(ctx, updateAgentAction,
		arg.Status,
		arg.Compensation,
		arg.TargetVersion,
		arg.UndoRefusal,
		arg.UpdatedAt,
		arg.ID,
		arg.ExpectedVersion,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected()
}

